"@type":"City","name":"Brattleboro","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Bennington","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Middlebury","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"St. Johnsbury","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Stowe","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Hartford","containedInPlace":{"@type":"State","name":"Vermont"}}],"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Snow load collapse","Flood and water damage claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://vermontinsuranceappraiser.com/#website","url":"https://vermontinsuranceappraiser.com/","name":"Vermont Insurance Appraiser","publisher":{"@id":"https://vermontinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/#webpage","url":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/","name":"Searchable Insurance Claim Glossary | 40 Terms","description":"A searchable insurance claim glossary: ACV, RCV, holdback, ice dam, snow load, umpire, O&P and more, each defined in plain English.","inLanguage":"en-US","isPartOf":{"@id":"https://vermontinsuranceappraiser.com/#website"},"about":{"@id":"https://vermontinsuranceappraiser.com/#business"},"publisher":{"@id":"https://vermontinsuranceappraiser.com/#business"},"dateModified":"2026-11-17","primaryImageOfPage":{"@type":"ImageObject","url":"https://vermontinsuranceappraiser.com/assets/img/photos/business-document.webp","width":1200,"height":900},"breadcrumb":{"@id":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://vermontinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Glossary","item":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/"}],"@id":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"The value of damaged property at the time of loss, usually replacement cost minus depreciation. Some policies pay only ACV."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while a home is repaired, often called Coverage D or loss of use."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the damage. Appraisal is designed to decide this, not coverage."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"A person each side names to value the loss. Policies usually require a competent and impartial appraiser."},{"@type":"DefinedTerm","name":"Collapse","description":"An additional coverage in many policies. Some define it narrowly as an abrupt falling down."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, barns, sheds and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing limits, deductibles, the insured property and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and obsolescence used to calculate ACV."},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds to, removes or changes coverage in the base policy."},{"@type":"DefinedTerm","name":"Exclusion","description":"Policy language removing certain causes or types of damage from coverage, such as flood."},{"@type":"DefinedTerm","name":"Flood","description":"Generally, rising surface water from rivers, rain or melting snow. Usually excluded from homeowners policies and covered by separate flood insurance."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld from the first payment until repairs are completed."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under roofing and leak inside."},{"@type":"DefinedTerm","name":"Impartial","description":"Without bias toward either side. Many appraisal clauses require impartial or disinterested appraisers."},{"@type":"DefinedTerm","name":"Like kind and quality","description":"Materials and workmanship equal to what existed before the loss."},{"@type":"DefinedTerm","name":"Line item","description":"One entry in an estimate, such as a quantity of shingles or a coat of paint, with a unit price."},{"@type":"DefinedTerm","name":"Matching","description":"Whether new materials must match undamaged ones so the repair is uniform. Policy wording and state rules vary."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps after a loss to prevent further damage, such as tarping or water extraction."},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, which writes most residential flood policies through participating carriers."},{"@type":"DefinedTerm","name":"Ordinance or law","description":"Coverage for added costs to meet building codes during repair. Often a percentage of Coverage A."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for managing a job, often 10% overhead plus 10% profit."},{"@type":"DefinedTerm","name":"Peril","description":"A cause of loss, such as fire, wind, hail or the weight of ice and snow."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, required by many policies when the insurer requests it."},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional hired by the policyholder to prepare and negotiate the whole claim."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the insurer pays after repairs are completed under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with like kind and quality, without deducting depreciation."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed, the foundation of any estimate."},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of snow and ice on a roof, measured in pounds per square foot."},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Sub-limit","description":"A lower limit within a policy for a certain kind of property or loss, such as mold or trees."},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy condition setting how long you have to sue the insurer. Vermont law may affect how it applies."},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missed or under-priced in the original estimate."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who decides the items the two appraisers cannot agree on."},{"@type":"DefinedTerm","name":"Vacancy","description":"A condition in many policies that limits coverage when a building has been empty for a set period."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors, with regional price lists."}],"@id":"https://vermontinsuranceappraiser.com/searchable-claim-glossary/#definedtermset"}]}</script>
</head>
